    positional = []
    i = 0
    while i < len(argv):
        a = argv[i]
        if a in ('--version',):
            print(VERSION); return 0
        if a in ('--help','-h'):
            print('Usage: task [flags...] [task...]\n\nRuns the specified task(s). Falls back to the "default" task if no task name\nwas specified, or lists all tasks if an unknown task name was specified.\n\nOptions:\n  -h, --help       Shows Task usage.\n      --version    Show Task version.\n  -i, --init       Creates a new Taskfile.yml in the current folder.\n  -d, --dir        Sets the directory in which Task will execute.\n  -t, --taskfile   Choose which Taskfile to run.')
            return 0
        if a in ('--init','-i'):
            init_path = 'Taskfile.yml'
            if i+1 < len(argv) and not argv[i+1].startswith('-'):
                init_path = argv[i+1]; i += 1
        elif a in ('--dir','-d') and i+1 < len(argv):
            directory = argv[i+1]; i += 1
        elif a.startswith('--dir='):
            directory=a.split('=',1)[1]
        elif a in ('--taskfile','-t') and i+1 < len(argv):
