        elif a.startswith('--taskfile='):
            taskfile=a.split('=',1)[1]
        elif a.startswith('-'):
            pass
        elif a != '--':
            positional.append(a)
        else:
            break
        i += 1
    if init_path is not None:
        if directory:
            init_path = os.path.join(directory, init_path)
        return initialize(init_path)
    base = os.path.abspath(directory or os.getcwd())
    candidates = [taskfile] if taskfile else ['Taskfile.yml','Taskfile.yaml','Taskfile.dist.yml','Taskfile.dist.yaml']
    found = None
    for d in [base] + list(_parents(base)):
        for name in candidates:
            if name and os.path.isfile(os.path.join(d,name)):
                found = os.path.join(d,name); break
        if found: break
    if not found:
        print('task: No Taskfile found at ""' + NO_TASKFILE, file=sys.stderr)
        return 100
    # The task runner is implemented by the main execution module when available.
    print('task: Taskfile execution unavailable', file=sys.stderr)
    return 1

def _parents(path):
    while True:
        parent=os.path.dirname(path)
        if parent == path: return
        yield parent
        path=parent

if __name__ == '__main__':
    raise SystemExit(main())

